 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const result: Query = {};
+
+  const input = query.startsWith("?") ? query.slice(1) : query;
+  if (input.length === 0) {
+    return result;
+  }
+
+  for (const pair of input.split("&")) {
+    if (pair.length === 0) {
+      continue;
+    }
+
+    const separator = pair.indexOf("=");
+    const rawKey = separator === -1 ? pair : pair.slice(0, separator);
+    const rawValue = separator === -1 ? "" : pair.slice(separator + 1);
+
+    const key = decodePart(rawKey);
+    const value = decodePart(rawValue);
+    const existing = result[key];
+
+    if (existing === undefined) {
+      result[key] = value;
+      continue;
+    }
+
+    if (Array.isArray(existing)) {
+      existing.push(value);
+    } else {
+      result[key] = [existing, value];
+    }
+  }
+
+  return result;
 }
+
+function decodePart(value: string): string {
+  const plusAsSpace = value.replace(/\+/g, " ");
+
+  try {
+    return decodeURIComponent(plusAsSpace);
+  } catch {
+    return plusAsSpace;
+  }
+}
